using System;using System.Drawing;using System.Runtime.InteropServices;using System.Security.Cryptography;using System.Text;using System.Windows.Interop;using Forms=System.Windows.Forms;
internal sealed class NativeTray:IDisposable{
 const uint Callback=0x8000+71;readonly IntPtr hwnd;readonly Icon icon;readonly Guid id;readonly HwndSource source;bool visible,disposed;
 internal Forms.ContextMenuStrip ContextMenuStrip;internal event EventHandler DoubleClick;
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Data{public uint cbSize;public IntPtr hwnd;public uint uid,flags,callback;public IntPtr icon;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string tip;public uint state,stateMask;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=256)]public string info;public uint version;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=64)]public string title;public uint infoFlags;public Guid guid;public IntPtr balloon;}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool Shell_NotifyIcon(uint message,ref Data data);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern uint RegisterWindowMessage(string text);
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr hwnd);
 readonly uint taskbarCreated=RegisterWindowMessage("TaskbarCreated");
 internal NativeTray(IntPtr handle,Icon picture){hwnd=handle;icon=picture;using(var sha=SHA256.Create()){byte[] bytes=sha.ComputeHash(Encoding.UTF8.GetBytes("Firefly-tray-"+RuntimeManager.Key+"-"+RuntimeManager.Root.ToLowerInvariant()));Array.Resize(ref bytes,16);id=new Guid(bytes);}source=HwndSource.FromHwnd(hwnd);source.AddHook(Hook);}
 Data Value(){return new Data{cbSize=(uint)Marshal.SizeOf(typeof(Data)),hwnd=hwnd,uid=71,flags=1|2|4|32|128,callback=Callback,icon=icon.Handle,tip="流萤",guid=id};}
 internal bool Visible{get{return visible;}set{if(value==visible)return;var d=Value();if(value){bool ok=Shell_NotifyIcon(0,ref d);RuntimeManager.Log("tray","NIM_ADD="+ok+" lastError-not-authoritative="+Marshal.GetLastWin32Error()+" bytes="+d.cbSize);if(ok){d.version=4;bool version=Shell_NotifyIcon(4,ref d);RuntimeManager.Log("tray","NIM_SETVERSION="+version);visible=true;}}else{Shell_NotifyIcon(2,ref d);visible=false;}}}
 IntPtr Hook(IntPtr h,int message,IntPtr w,IntPtr l,ref bool handled){if(disposed)return IntPtr.Zero;if((uint)message==taskbarCreated){visible=false;Visible=true;}if((uint)message==Callback){int code=(int)(l.ToInt64()&0xffff);if(code==0x205||code==0x7b||code==0x203||code==0x400||code==0x401)RuntimeManager.Log("tray","callback="+code);if(code==0x205||code==0x7b){SetForegroundWindow(hwnd);if(ContextMenuStrip!=null)ContextMenuStrip.Show(Forms.Cursor.Position);}else if(code==0x203||code==0x400||code==0x401){SetForegroundWindow(hwnd);if(DoubleClick!=null)DoubleClick(this,EventArgs.Empty);}handled=true;}return IntPtr.Zero;}
 public void Dispose(){if(disposed)return;disposed=true;try{Visible=false;}catch(Exception ex){RuntimeManager.Log("tray","delete-warning "+ex.GetType().Name);}finally{if(source!=null)try{source.RemoveHook(Hook);}catch(Exception ex){RuntimeManager.Log("tray","hook-dispose-warning "+ex.GetType().Name);}}}
}
